&lt;p&gt;D&lt;sub&gt;1&lt;/sub&gt; = 18 days , D&lt;sub&gt;2&lt;/sub&gt; = 20 days&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formula Used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;(M&lt;sub&gt;1&lt;/sub&gt; x D&lt;sub&gt;1&lt;/sub&gt; x T&lt;sub&gt;1&lt;/sub&gt;)/W&lt;sub&gt;1&lt;/sub&gt; = (M&lt;sub&gt;2&lt;/sub&gt; x D&lt;sub&gt;2&lt;/sub&gt; x T&lt;sub&gt;2&lt;/sub&gt;)/W&lt;sub&gt;2&lt;/sub&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Substittuting the values in the formula&lt;/p&gt;

&lt;p&gt;&amp;rArr; (210&amp;nbsp;&amp;times; 18&amp;nbsp;&amp;times; 12)/1 = (M&lt;sub&gt;2&lt;/sub&gt;&amp;nbsp;&amp;times; 20&amp;nbsp;&amp;times; 14)/1&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;M&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= 3&amp;nbsp;&amp;times; 18&amp;nbsp;&amp;times; 3&amp;nbsp;= 162&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4;&amp;nbsp;162 men are required to finish the job in 20 days working 14 hours a day&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;दिया गया है:&lt;/font&gt;&lt;/font&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;M1 = 210&amp;nbsp;पुरुष,&amp;nbsp;&lt;/font&gt;&lt;/font&gt;&lt;/p&gt;

&lt;p&gt;T&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;1&lt;/span&gt;&amp;nbsp;= 12 घंटे, T&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= 14 घंटे&lt;/p&gt;

&lt;p&gt;D&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;1&lt;/span&gt;&amp;nbsp;= 18 दिन, D&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= 20 दिन&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;प्रयुक्त सूत्र:&lt;/font&gt;&lt;/font&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;(M&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;1&lt;/span&gt;&amp;nbsp;x D&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;1&lt;/span&gt;&amp;nbsp;x T&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;1&lt;/span&gt;)/W&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;1&lt;/span&gt;&amp;nbsp;= (M&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;x D&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;x T&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;)/W&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;/p&gt;

&lt;div&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;गणना:&lt;/font&gt;&lt;/font&gt;&lt;/strong&gt;&lt;/div&gt;

&lt;div&gt;&amp;nbsp;&lt;/div&gt;

&lt;div&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सूत्र में मानों को प्रतिस्थापित करने पर,&amp;nbsp;&lt;/font&gt;&lt;/font&gt;&lt;/div&gt;

&lt;p&gt;&amp;rArr; (210&amp;nbsp;&amp;times; 18&amp;nbsp;&amp;times; 12)/1 = (M&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; bottom: -0.25em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;&amp;times; 20&amp;nbsp;&amp;times; 14)/1&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;M&lt;span style=&quot;position: relative; line-height: 0; vertical-align: baseline; bottom: -0.25em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= 3&amp;nbsp;&amp;times; 18&amp;nbsp;&amp;times; 3&amp;nbsp;= 162&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;there4;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;162 पुरुषों को&lt;/font&gt;&lt;/font&gt;&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;20 दिनों में कार्य&amp;nbsp;समाप्त&amp;nbsp;करने के लिए&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;दिन में&lt;/span&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;14 घंटे कार्य करके की आवश्यकता&amp;nbsp;है।&amp;nbsp;&lt;/font&gt;&lt;/font&gt;&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;A steamer can move 36 km in downstream = 6 hr&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;A steamer can move 36 km in upstream = 10&amp;nbsp;hr&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Formula used:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Speed of the stream = (Speed in downstream - speed in upstream)/2&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Calculation:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Speed in downstream = 36/6 = 6 km/h&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Speed in upstream = 36/10 = 3.6 km/h&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Speed of stream = (6 - 3.6)/2 = 1.2 km/h&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; The speed of the stream is 1.2 km/h.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;दिया गया है:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;एक स्टीमर द्वारा धारा के अनुकूल&amp;nbsp;36 किमी की दूरी तय&amp;nbsp;करने में लगा समय = 6 घंटा&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;एक स्टीमर &lt;/span&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;द्वारा&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;धारा के प्रतिकूल&amp;nbsp;36 किमी &lt;/span&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;की दू&lt;/span&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;री तय&lt;/span&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;nbsp;करने में लगा समय&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;= 10 घंटा&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;प्रयुक्त सूत्र:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;धारा की गति = (धारा के अनुकूल गति - धारा के प्रतिकूल गति)/2&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;गणना:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;धारा के अनुकूल गति&amp;nbsp;= 36/6 = 6 किमी/घंटा&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;धारा के प्रतिकूल गति = 36/10 = 3.6 किमी&lt;/span&gt;&lt;span style=&quot;&quot;&gt;/घंटा&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;धारा की गति = (6 - 3.6)/2 = 1.2 किमी&lt;/span&gt;&lt;span style=&quot;&quot;&gt;/घंटा&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; धारा की गति 1.2&amp;nbsp;किमी/घंटा है।&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

