&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Radius (r) = 10 cm&lt;/p&gt;

&lt;p&gt;Ratio (CSA : TSA) = 4 : 5&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formula used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;CSA = &amp;pi;rl&lt;/p&gt;

&lt;p&gt;TSA = &amp;pi;r(l + r)&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; &amp;pi;rl : &amp;pi;r(l + r) = 4 : 5&lt;/p&gt;

&lt;p&gt;&amp;rArr; l : (l + r) = 4 : 5&lt;/p&gt;

&lt;p&gt;&amp;rArr; 5l = 4(l + r)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 5l = 4l + 4r&lt;/p&gt;

&lt;p&gt;&amp;rArr; l = 4r&lt;/p&gt;

&lt;p&gt;&amp;rArr; l = 4 &amp;times; 10 = 40 cm&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; Slant height = 40 cm.&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;div&gt;त्रिज्या = 10 सेमी&lt;/div&gt;

